content:
===== FILE: styles.css =====
:root {
  --primary: #c81623;
  --primary-dark: #9e111b;
  --text-main: #1a1a1a;
  --text-secondary: #4a4a4a;
  --text-muted: #767676;
  --bg-page: #f5f6f7;
  --bg-card: #ffffff;
  --bg-subtle: #eff1f3;
  --border: #e2e4e8;
  --accent-blue: #165dff;
  --success-green: #00b42a;
  --font-sans: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "WenQuanYi Micro Hei", -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: "Noto Serif SC", "Songti SC", "STSong", "SimSun", serif;
  --max-width: 1320px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.15s ease;
}

a:hover {
  color: var(--primary);
}

img {
  max-width: 100%;
  display: block;
  object-fit: cover;
}

ul {
  list-style: none;
}

/* Top Utility Bar */
.top-bar {
  background-color: #111317;
  color: #d1d5db;
  font-size: 13px;
  border-bottom: 1px solid #262930;
}

.top-bar-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 8px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.top-bar-left, .top-bar-right {
  display: flex;
  align-items: center;
  gap: 20px;
}

.market-ticker {
  display: flex;
  gap: 16px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.ticker-up {
  color: #f53f3f;
}

.ticker-down {
  color: #00b42a;
}

/* Main Header */
.site-header {
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
}

.header-main {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 18px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  background-color: var(--primary);
  color: #fff;
  font-weight: 800;
  font-size: 24px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  letter-spacing: 1px;
}

.brand-text h1 {
  font-size: 28px;
  font-weight: 900;
  letter-spacing: 2px;
  line-height: 1.1;
  color: #111;
}

.brand-text span {
  font-size: 12px;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.search-box {
  display: flex;
  align-items: center;
  background: var(--bg-subtle);
  border: 1px solid transparent;
  border-radius: 4px;
  padding: 4px 4px 4px 12px;
  width: 280px;
  transition: all 0.2s;
}

.search-box:focus-within {
  background: #fff;
  border-color: var(--primary);
}

.search-box input {
  border: none;
  background: transparent;
  outline: none;
  width: 100%;
  font-size: 14px;
  color: var(--text-main);
}

.search-box button {
  background: var(--primary);
  color: #fff;
  border: none;
  padding: 6px 14px;
  border-radius: 3px;
  font-size: 13px;
  cursor: pointer;
  font-weight: 500;
  white-space: nowrap;
}

.search-box button:hover {
  background: var(--primary-dark);
}

.commute-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background-color: #fff3f3;
  color: var(--primary);
  border: 1px solid #ffccc7;
  padding: 7px 14px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
}

.commute-btn:hover {
  background-color: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

/* Primary Navigation */
.main-nav {
  border-top: 1px solid var(--border);
  background: #fff;
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
}

.nav-inner a {
  padding: 12px 16px;
  font-size: 16px;
  font-weight: 600;
  color: var(--text-main);
  position: relative;
  white-space: nowrap;
}

.nav-inner a:hover,
.nav-inner a.active {
  color: var(--primary);
}

.nav-inner a.active::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 16px;
  right: 16px;
  height: 3px;
  background-color: var(--primary);
}

.nav-tag {
  font-size: 11px;
  background: var(--bg-subtle);
  color: var(--text-secondary);
  padding: 2px 6px;
  border-radius: 2px;
  margin-left: 4px;
  font-weight: normal;
}

/* Breaking News Banner */
.breaking-bar {
  max-width: var(--max-width);
  margin: 16px auto 0;
  padding: 0 24px;
}

.breaking-inner {
  background: #fff;
  border: 1px solid var(--border);
  border-left: 4px solid var(--primary);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-radius: 2px;
}

.breaking-label {
  background: var(--primary);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 2px;
  white-space: nowrap;
}

.breaking-content {
  flex: 1;
  font-size: 14px;
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.breaking-time {
  color: var(--text-muted);
  font-size: 12px;
  margin-right: 8px;
  font-family: monospace;
}

/* Main Container Layout */
.container {
  max-width: var(--max-width);
  margin: 20px auto 48px;
  padding: 0 24px;
}

.home-grid {
  display: grid;
  grid-template-columns: 280px 1fr 320px;
  gap: 24px;
  align-items: start;
}

.category-grid {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 28px;
  align-items: start;
}

.article-grid {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 32px;
  align-items: start;
}

/* Cards & Panels */
.panel {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 20px;
  margin-bottom: 24px;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 2px solid #111;
}

.panel-title {
  font-size: 18px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 8px;
}

.panel-title::before {
  content: "";
  display: inline-block;
  width: 4px;
  height: 18px;
  background: var(--primary);
}

.panel-more {
  font-size: 13px;
  color: var(--text-muted);
}

/* Left Column: 24h Live Flash */
.flash-list {
  position: relative;
  padding-left: 14px;
  border-left: 1px solid var(--border);
}

.flash-item {
  position: relative;
  margin-bottom: 18px;
}

.flash-item:last-child {
  margin-bottom: 0;
}

.flash-item::before {
  content: "";
  position: absolute;
  left: -18px;
  top: 6px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--primary);
  border: 2px solid #fff;
}

.flash-time {
  font-size: 12px;
  font-weight: 700;
  color: var(--primary);
  font-family: monospace;
  display: block;
  margin-bottom: 3px;
}

.flash-text {
  font-size: 14px;
  color: var(--text-main);
  line-height: 1.5;
}

.flash-item.important .flash-text {
  font-weight: 600;
  color: #b5121e;
}

/* Center Column: Lead Story & Feed */
.lead-story {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 24px;
}

.lead-image-wrap {
  position: relative;
  height: 360px;
  overflow: hidden;
}

.lead-image-wrap img {
  width: 100%;
  height: 100%;
  transition: transform 0.3s ease;
}

.lead-story:hover .lead-image-wrap img {
  transform: scale(1.02);
}

.lead-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--primary);
  color: #fff;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 700;
  border-radius: 2px;
}

.lead-body {
  padding: 24px;
}

.lead-title {
  font-size: 26px;
  font-weight: 800;
  line-height: 1.35;
  margin-bottom: 12px;
}

.lead-excerpt {
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 16px;
  line-height: 1.65;
}

.meta-info {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 13px;
  color: var(--text-muted);
}

.meta-tag {
  color: var(--primary);
  font-weight: 600;
}

.read-time {
  background: var(--bg-subtle);
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 12px;
  color: var(--text-secondary);
}

/* Sub-lead 2-column grid */
.sub-leads {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

.sub-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.sub-card img {
  height: 160px;
  width: 100%;
}

.sub-card-body {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.sub-card-title {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 10px;
}

/* News Feed List */
.feed-tabs {
  display: flex;
  gap: 20px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
}

.feed-tab {
  padding: 8px 4px 12px;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  border-bottom: 3px solid transparent;
  color: var(--text-secondary);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}

.feed-tab.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

.news-item {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 0;
  border-bottom: 1px solid var(--border);
}

.news-item:first-child {
  padding-top: 4px;
}

.news-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.news-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.news-title {
  font-size: 19px;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 8px;
}

.news-summary {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.news-thumb {
  width: 190px;
  height: 124px;
  border-radius: 3px;
  overflow: hidden;
  flex-shrink: 0;
}

.news-thumb img {
  width: 100%;
  height: 100%;
}

/* Right Column: Commute Brief & Hot Ranking */
.commute-card {
  background: linear-gradient(180deg, #fff8f8 0%, #ffffff 100%);
  border: 1px solid #ffd8d6;
}

.commute-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.commute-badge {
  background: var(--primary);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 3px;
}

.commute-list li {
  padding: 10px 0;
  border-bottom: 1px dashed #e8e8e8;
  font-size: 14px;
  line-height: 1.5;
}

.commute-list li:last-child {
  border-bottom: none;
}

.commute-num {
  font-weight: 800;
  color: var(--primary);
  margin-right: 6px;
}

/* Hot Ranking List */
.rank-list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 11px 0;
  border-bottom: 1px solid var(--bg-subtle);
}

.rank-list li:last-child {
  border-bottom: none;
}

.rank-num {
  width: 22px;
  height: 22px;
  border-radius: 3px;
  background: var(--bg-subtle);
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 2px;
}

.rank-list li:nth-child(1) .rank-num {
  background: #f53f3f;
  color: #fff;
}
.rank-list li:nth-child(2) .rank-num {
  background: #ff7d00;
  color: #fff;
}
.rank-list li:nth-child(3) .rank-num {
  background: #ffb400;
  color: #fff;
}

.rank-title {
  font-size: 14px;
  line-height: 1.45;
  flex: 1;
}

/* Category Page Specifics */
.category-banner {
  background: #141821;
  color: #fff;
  padding: 28px 32px;
  border-radius: 4px;
  margin-bottom: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}

.category-banner h2 {
  font-size: 28px;
  font-weight: 800;
  margin-bottom: 6px;
}

.category-banner p {
  color: #9ca3af;
  font-size: 14px;
}

.category-metrics {
  display: flex;
  gap: 20px;
}

.metric-box {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  padding: 10px 16px;
  border-radius: 4px;
  min-width: 130px;
}

.metric-name {
  font-size: 12px;
  color: #9ca3af;
  display: block;
}

.metric-val {
  font-size: 18px;
  font-weight: 700;
  font-family: monospace;
}

.filter-bar {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.filter-btn {
  padding: 7px 16px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  color: var(--text-secondary);
}

.filter-btn.active,
.filter-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

/* Article Page Specifics */
.article-main {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 36px 44px;
}

.breadcrumb {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 20px;
}

.breadcrumb a {
  color: var(--text-secondary);
}

.article-headline {
  font-size: 32px;
  font-weight: 800;
  line-height: 1.35;
  margin-bottom: 20px;
  color: #111;
}

.article-byline {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 20px;
  margin-bottom: 24px;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
  gap: 12px;
}

.author-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.author-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}

.author-meta {
  font-size: 13px;
  color: var(--text-muted);
}

.author-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-main);
  margin-right: 8px;
}

.article-tools {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tool-btn {
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  padding: 5px 12px;
  border-radius: 3px;
  font-size: 13px;
  cursor: pointer;
  color: var(--text-secondary);
}

.tool-btn:hover, .tool-btn.active {
  border-color: var(--primary);
  color: var(--primary);
}

/* Key Takeaways Box for Commuters */
.key-takeaways {
  background: #f8f9fb;
  border-left: 4px solid var(--primary);
  padding: 20px 24px;
  margin-bottom: 28px;
  border-radius: 0 4px 4px 0;
}

.takeaways-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.takeaways-list {
  list-style: disc;
  padding-left: 20px;
}

.takeaways-list li {
  font-size: 15px;
  color: var(--text-main);
  margin-bottom: 6px;
  line-height: 1.6;
}

.article-content {
  font-size: 17px;
  line-height: 1.85;
  color: #222;
}

.article-content p {
  margin-bottom: 22px;
}

.article-content h3 {
  font-size: 21px;
  font-weight: 800;
  margin: 32px 0 16px;
  padding-left: 12px;
  border-left: 4px solid var(--primary);
  line-height: 1.3;
}

.article-figure {
  margin: 28px 0;
  background: var(--bg-subtle);
  border-radius: 4px;
  overflow: hidden;
}

.article-figure img {
  width: 100%;
  max-height: 440px;
}

.article-figure figcaption {
  padding: 10px 16px;
  font-size: 13px;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  margin: 24px 0;
  font-size: 14px;
}

.data-table th, .data-table td {
  border: 1px solid var(--border);
  padding: 12px 14px;
  text-align: left;
}

.data-table th {
  background: var(--bg-subtle);
  font-weight: 700;
}

/* Modal for 3-Minute Commute Edition */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 20px;
}

.modal-overlay.open {
  display: flex;
}

.modal-box {
  background: #fff;
  max-width: 680px;
  width: 100%;
  max-height: 85vh;
  border-radius: 6px;
  overflow-y: auto;
  box-shadow: 0 20px 40px rgba(0,0,0,0.25);
}

.modal-header {
  background: var(--primary);
  color: #fff;
  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-header h3 {
  font-size: 20px;
  font-weight: 800;
}

.modal-close {
  background: rgba(255,255,255,0.2);
  border: none;
  color: #fff;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-size: 18px;
  cursor: pointer;
}

.modal-body {
  padding: 24px;
}

.modal-item {
  padding-bottom: 16px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border);
}

.modal-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.modal-item h4 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 6px;
}

.modal-item p {
  font-size: 14px;
  color: var(--text-secondary);
}

/* About Page Specifics */
.about-hero {
  background: #141821;
  color: #fff;
  padding: 56px 40px;
  border-radius: 4px;
  margin-bottom: 32px;
  text-align: center;
}

.about-hero h2 {
  font-size: 36px;
  font-weight: 900;
  margin-bottom: 12px;
  letter-spacing: 1px;
}

.about-hero p {
  font-size: 17px;
  color: #d1d5db;
  max-width: 720px;
  margin: 0 auto;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 32px;
}

.stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 24px;
  text-align: center;
  border-radius: 4px;
}

.stat-number {
  font-size: 32px;
  font-weight: 900;
  color: var(--primary);
  display: block;
  margin-bottom: 4px;
}

.stat-desc {
  font-size: 14px;
  color: var(--text-secondary);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 16px;
}

.team-card {
  border: 1px solid var(--border);
  padding: 20px;
  border-radius: 4px;
